import base64, os

files = {}

files['config.py'] = base64.b64decode('').decode('utf-8')

files['agents/risk_manager.py'] = base64.b64decode('').decode('utf-8')

for path, content in files.items():
    os.makedirs(os.path.dirname(path) if os.path.dirname(path) else '.', exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(content)
    print('Written: ' + path)
print('Done')